'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostEqual = require( '@stdlib/assert/is-almost-equal-float64array' );
var dorgbr = require( './../lib/dorgbr.js' );


// FIXTURES //

var Q_M_GE_K_COL_MAJ = require( './fixtures/q_m_ge_k_col_maj.json' );
var Q_M_LT_K_COL_MAJ = require( './fixtures/q_m_lt_k_col_maj.json' );
var P_K_LT_N_COL_MAJ = require( './fixtures/p_k_lt_n_col_maj.json' );
var P_K_GE_N_COL_MAJ = require( './fixtures/p_k_ge_n_col_maj.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dorgbr, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( dorgbr.length, 10, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var WORK;
	var TAU;
	var A;
	var i;

	A = new Float64Array( [ 1, 0, 0, 0, 1, 0 ] );
	TAU = new Float64Array( [ 2, 2 ] );
	WORK = new Float64Array( 10 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dorgbr( value, 'Q', 3, 2, 2, A, 3, TAU, WORK, 10 );
		};
	}
});

