tape( 'the function quick returns when `LWORK` is equal to -1', function test( t ) {
	var expectedWORK;
	var expectedA;
	var info;
	var WORK;
	var TAU;
	var A;

	A = new Float64Array( [ 1, 0.2, -0.1, 0.3, 0, 1, 0.4, -0.2, 0, 0, 1, 0.5 ] );
	TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	WORK = new Float64Array( 10 );

	expectedA = A;
	expectedWORK = WORK;
	expectedWORK[ 0 ] = 96;

	info = dorgbr( 'column-major', 'Q', 4, 3, 3, A, 4, TAU, WORK, -1 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( A, expectedA, 'returns expected value' );
	t.strictEqual( WORK, expectedWORK, 'returns expected value' );
	t.end();
});

