tape( 'the function generates the orthogonal matrix `Q` (`m >= k`, column-major)', function test( t ) {
	var expectedWORK;
	var expectedA;
	var info;
	var data;
	var WORK;
	var TAU;
	var A;

	data = Q_M_GE_K_COL_MAJ;

	A = new Float64Array( data.A );
	TAU = new Float64Array( data.TAU );
	WORK = new Float64Array( data.WORK );

	expectedA = new Float64Array( data.A_out );
	expectedWORK = new Float64Array( data.WORK_out );

	info = dorgbr( data.order, data.vect, data.M, data.N, data.K, A, data.LDA, TAU, WORK, data.LWORK );
	t.strictEqual( info, data.info, 'returns expected value' );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( WORK, expectedWORK, 1 ), true, 'returns expected value' );
	t.end();
});

